<?php include "../includes/cek_session.php";include "../config/koneksi.php";$id=(int)($_GET['id']??0);$t=mysqli_fetch_assoc(mysqli_query($koneksi,"SELECT t.*,u.nama_lengkap,COALESCE(p.nama_pelanggan,'Pelanggan Umum') pelanggan FROM tb_transaksi t JOIN tb_pengguna u ON u.id_pengguna=t.id_pengguna LEFT JOIN tb_pelanggan p ON p.id_pelanggan=t.id_pelanggan WHERE t.id_transaksi=$id"));if(!$t){header("Location:index.php");exit;}$d=mysqli_query($koneksi,"SELECT d.*,b.nama_barang FROM tb_detail_transaksi d JOIN tb_barang b ON b.id_barang=d.id_barang WHERE d.id_transaksi=$id");$title="Detail Transaksi";include "../includes/header.php";?>
<div class="panel receipt"><div class="no-print"><a class="btn light" href="index.php">Kembali</a><button class="btn" onclick="window.print()">Cetak</button></div><h2>Kasir Nucky</h2><p class="text-right">No: <?=htmlspecialchars($t['no_transaksi'])?><br><?=htmlspecialchars($t['tanggal'])?></p><p>Kasir: <?=htmlspecialchars($t['nama_lengkap'])?><br>Pelanggan: <?=htmlspecialchars($t['pelanggan'])?></p><table><tr><th>Barang</th><th>Qty</th><th>Harga</th><th>Subtotal</th></tr><?php while($x=mysqli_fetch_assoc($d)):?><tr><td><?=htmlspecialchars($x['nama_barang'])?></td><td><?=$x['jumlah']?></td><td>Rp <?=number_format($x['harga'],0,',','.')?></td><td>Rp <?=number_format($x['subtotal'],0,',','.')?></td></tr><?php endwhile;?></table><p class="text-right total">Total Rp <?=number_format($t['total_bayar'],0,',','.')?></p></div><?php include "../includes/footer.php";?>